import { api } from "@/lib/api";
import type { DesktopHandoff } from "@/lib/types";

/**
 * Desktop SSO handoff (#157).
 *
 * The desktop app opens `{server}/#/login?desktop_state=<state>` in the system
 * browser. The state must survive the OIDC redirect (the provider sends the
 * browser back to `/#/login?oidc_code=…`, without the parameter), so it is kept
 * in `sessionStorage` until the authenticated page hands the session back.
 *
 * The state is an opaque 43-64 character token generated by the desktop app. It
 * is never a credential: the handoff endpoint requires an authenticated
 * session, and the desktop redeems the returned one-time code through the
 * existing exchange.
 */

/** Query parameter the desktop app appends to the login URL. */
export const DESKTOP_STATE_PARAM = "desktop_state";

const STORAGE_KEY = "ludex.desktop-state";

/** 32 random bytes in base64url (43) or hex (64), with headroom. */
export function isValidDesktopState(value: string | null | undefined): value is string {
  if (!value) return false;
  return value.length >= 43 && value.length <= 128 && /^[A-Za-z0-9_-]+$/.test(value);
}

/**
 * Reads `desktop_state` from a location search string (React Router's
 * `useSearchParams` or `window.location.search`, with or without the leading
 * `?`). Returns `null` for anything that does not look like a desktop state.
 */
export function readDesktopStateFromSearch(search: string | URLSearchParams): string | null {
  const params = typeof search === "string" ? new URLSearchParams(search.replace(/^[?#]/, "")) : search;
  const value = params.get(DESKTOP_STATE_PARAM);
  return isValidDesktopState(value) ? value : null;
}

/** Keeps the state across the OIDC redirect. */
export function rememberDesktopState(state: string): void {
  try {
    sessionStorage.setItem(STORAGE_KEY, state);
  } catch {
    /* private mode: the handoff only works within this page load */
  }
}

/** The state remembered for this tab, if any. */
export function pendingDesktopState(): string | null {
  try {
    const value = sessionStorage.getItem(STORAGE_KEY);
    return isValidDesktopState(value) ? value : null;
  } catch {
    return null;
  }
}

/** Drops the remembered state once the session has been handed back. */
export function forgetDesktopState(): void {
  try {
    sessionStorage.removeItem(STORAGE_KEY);
  } catch {
    /* nothing to clean up */
  }
}

/**
 * Binds the current web session to the desktop attempt. Called once, after a
 * successful sign-in and only when a desktop state is pending.
 */
export function createDesktopHandoff(state: string): Promise<DesktopHandoff> {
  return api.createDesktopHandoff(state);
}
